window.AUTH=window.AUTH||{};window.AUTH["01-653"]={"d":"01-653","id":"2002/01-653","n":"Federal Communications Commission v. Nextwave Personal Communications, Inc.","src":["osg"],"briefs":[{"k":"reply","label":"Reply brief for the Federal Communications Commission","date":"","url":"https://www.justice.gov/osg/media/193536/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/fcc-v-nextwave-reply-merits","n":1},{"k":"petitioner","label":"Brief for the Federal Communications Commission","date":"","url":"https://www.justice.gov/osg/media/220216/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/fcc-v-nextwave-and-artic-slope-v-nextwave-brief-merits","n":66}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep537/usrep537293/usrep537293.pdf","tr":false,"items":[{"t":"case","label":"Bryan v. Rainwater","cite":"254 B.R. 273","y":2000,"court":"Bankr. N.D. Ala.","url":"https://www.courtlistener.com/c/B.R./254/273/","by":{"0":"3"}},{"t":"case","label":"Adventure Res., Inc. v. Holland","cite":"137 F.3d 786","y":1998,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/137/786/","by":{"1":"34"}},{"t":"case","label":"Almendarez-Torres v. United States","cite":"523 U.S. 224","y":1998,"id":"1997/96-6839","sc":1,"sum":"The Court held that subsection (b)(2) of 8 USC section 1326(a) is a penalty provision, which authorizes a court to increase the sentence for a recidivist, and does not define a separate crime. \"[W]e note that the relevant statutory subject matter is recidivism,\" wrote Justice Breyer, \"[t]hat subject matter -- prior commission of a serious crime -- is as typical a sentencing factor as one might imagine.\" Therefore, neither subsection (b)(2) nor the due process clause of the Fifth Amendment required that the government charge a prior aggravated felony conviction in the alien's indictment for the imposition of a sentence more than 2 years.","sumSrc":"Oyez","by":{"1":"40"}},{"t":"case","label":"Board of Governors v. MCorp. Fin., Inc.","cite":"502 U.S. 32","y":1991,"id":"1991/90-913","sc":1,"sum":"The District Court lacked jurisdiction to enjoin either regulatory proceeding.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"44"}},{"t":"case","label":"Consolidated Gas, Elec. Light & Power Co. v. United Rys. & Elec. Co.","cite":"85 F.2d 799","y":1936,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/85/799/","by":{"1":"35"}},{"t":"case","label":"Crawford Fitting Co. v. J.T. Gibbons, Inc.","cite":"482 U.S. 437","y":1987,"id":"1986/86-322","sc":1,"sum":"When a prevailing party seeks reimbursement for fees paid to its expert witnesses, a federal court is bound by the limits of § 1821(b), absent contract or explicit statutory authority to the contrary. There is no merit to petitioners' contentions that, since § 1920 lists expenses which a court \"may\" tax as costs, it only authorizes taxation of such items and does not preclude taxation for other items or amounts in …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"D.H. Overmyer Telecasting Co. v. Lake Erie Comm., Inc.","cite":"35 B.R. 400","y":1983,"court":"Bankr. N.D. Ohio","url":"https://www.courtlistener.com/c/B.R./35/400/","by":{"1":"28, 32, 42"}},{"t":"case","label":"Duffy v. Dollison","cite":"734 F.2d 265","y":1984,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/734/265/","by":{"1":"42"}},{"t":"case","label":"FAA v. Gull Air, Inc.","cite":"890 F.2d 1255","y":1989,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/890/1255/","by":{"1":"32"}},{"t":"case","label":"FCC v. Sanders Bros. Radio Station","cite":"309 U.S. 470","y":1940,"id":"scdb/1939-112","sc":1,"sum":"1. A fundamental question as to the function and powers of the Federal Communications Commission was raised in this case and, on the record, is open here.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"46"}},{"t":"case","label":"FCC v. WOKO, Inc.","cite":"329 U.S. 223","y":1946,"id":"scdb/1946-015","sc":1,"sum":"A corporation, which had operated a radio station for some years and appeared to have rendered public service of acceptable quality and to be able to continue, was denied a renewal of its license by the Federal Communications Commission on the ground that it could not be entrusted with the responsibilities of a licensee, because the Commission found that it had misrepresented the true ownership of its capital stock …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"2, 22"}},{"t":"case","label":"F.L. Crowder v. FCC","cite":"399 F.2d 569","y":1968,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/399/569/","by":{"1":"46"}},{"t":"case","label":"Federal Power Comm’n v. Idaho Power Co.","cite":"344 U.S. 17","y":1952,"id":"scdb/1952-005","sc":1,"sum":"Under § 4 (e) of the Federal Power Act, the Federal Power Commission issued to a power company a license to construct, operate and maintain a hydroelectric project including a dam, power plant and transmission lines on public lands, subject to the condition that the company permit the interconnection of transmission facilities of the United States with the company's transmission lines and the transfer over those …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28"}},{"t":"case","label":"Federal’s, Inc. v. Edmonton Inv. Co.","cite":"555 F.2d 557","y":1977,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/555/557/","by":{"1":"35"}},{"t":"case","label":"Johnson v. Edinboro State Coll.","cite":"728 F.2d 163","y":1984,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/728/163/","by":{"1":"30"}},{"t":"case","label":"Lee v. Schweiker","cite":"739 F.2d 870","y":1984,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/739/870/","by":{"1":"34"}},{"t":"case","label":"Midlantic Nat’l Bank v. New Jersey Dep’t of Envtl. Prot.","cite":"474 U.S. 494","y":1986,"id":"1985/84-801","sc":1,"sum":"A trustee in bankruptcy may not abandon property in contravention of a state statute or regulation that is reasonably designed to protect the public health or safety from identified hazards. Congress did not intend for §554(a) to pre-empt all state and local laws. A bankruptcy court does not have the power to authorize an abandonment without formulatResources Corp., Debtor v. City of New York et al., and O'Neill, …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"44"}},{"t":"case","label":"Moody v. Amoco Oil Co.","cite":"734 F.2d 1200","y":1984,"url":"https://www.courtlistener.com/c/F.2d/734/1200/","by":{"1":"32"}},{"t":"case","label":"Morton v. Mancari","cite":"417 U.S. 535","y":1974,"id":"1973/73-362","sc":1,"op":1,"sum":"In addition, the Court held that Section 472 did not constitute discrimination in violation of the Fifth Amendment. Again, Justice Blackmun cited the history of \"special treatment\" granted to Indians.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Mountain Solutions, Ltd. v. FCC","cite":"197 F.3d 512","y":1999,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/197/512/","by":{"1":"5, 25, 38, 41"}},{"t":"case","label":"NLRB v. Bildisco","cite":"465 U.S. 513","y":1984,"id":"1983/82-818","sc":1,"sum":"Section 365(a) of the Bankruptcy Code (Code) provides that, with certain exceptions, the trustee, subject to the Bankruptcy Court's approval, may assume or reject \"any executory contract\" of the debtor. In April 1980, respondent debtor (hereafter respondent), a building supplies distributor, filed a voluntary petition in bankruptcy for reorganization under Chapter 11 of the Code, and was subsequently authorized by …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"33"}},{"t":"case","label":"Nathanson v. NLRB","cite":"344 U.S. 25","y":1952,"id":"scdb/1952-006","sc":1,"sum":"1.. The Board is a \"creditor\" as respects the\" back-pay awards, within the meaning of the Bankruptcy Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"P&R Temmer v. FCC","cite":"743 F.2d 918","y":1984,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/743/918/","by":{"1":"28"}},{"t":"case","label":"Perez v. Campbell","cite":"402 U.S 637","y":1971,"url":"https://www.courtlistener.com/c/U.S/402/637/","op":3,"by":{"1":"18"}},{"t":"case","label":"Regents of the Univ. Sys. v. Carroll","cite":"338 U.S. 586","y":1950,"id":"scdb/1949-037","sc":1,"sum":"The judgment of the state court did not contravene the Supremacy Clause of Article VI of the Constitution.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"27"}},{"t":"case","label":"Scripps-Howard Radio, Inc. v. FCC","cite":"316 U.S. 4","y":1942,"id":"scdb/1941-046","sc":1,"by":{"1":"2, 15, 22, 27"}},{"t":"case","label":"U.S. Airwaves, Inc. v. FCC","cite":"232 F.3d 227","y":2000,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/232/227/","by":{"1":"45"}},{"t":"case","label":"Wainer v. A.J. Equities, Ltd.","cite":"984 F.2d 679","y":1993,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/984/679/","by":{"1":"35"}},{"t":"case","label":"West Virginia Univ. Hosps., Inc. v. Casey","cite":"499 U.S. 83","y":1991,"id":"1990/89-994","sc":1,"sum":"Fees for services rendered by experts in civil rights litigation may not be shifted to the losing party as part of \"a reasonable attorney's fee\" under § 1988.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","by":{"1":"31"}},{"t":"usc","label":"11 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/11/101","subs":["(5)(A)","(12)"],"stext":{"head":"§101. Definitions","paras":[[0,"In this title the following definitions shall apply:"],[1,"(1) The term \"accountant\" means accountant authorized under applicable law to practice public accounting, and includes professional accounting association, corporation, or partnership, if so authorized."],[1,"(2) The term \"affiliate\" means—"],[2,"(A) entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(B) corporation 20 percent or more of whose outstanding voting securities are directly or indirectly owned, controlled, or held with power to vote, by the debtor, or by an entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(C) person whose business is operated under a lease or operating agreement by a debtor, or person substantially all of whose property is operated under an operating agreement with the debtor; or"],[2,"(D) entity that operates the business or substantially all of the property of the debtor under a lease or operating agreement."],[1,"(3) The term \"assisted person\" means any person whose debts consist primarily of consumer debts and the value of whose nonexempt property is less than $150,000.1"],[1,"(4) The term \"attorney\" means attorney, professional law association, corporation, or partnership, authorized under applicable law to practice law."],[1,"(4A) The term \"bankruptcy assistance\" means any goods or services sold or otherwise provided to an assisted person with the express or implied purpose of providing information, advice, counsel, document preparation, or filing, or attendance at a creditors' meeting or appearing in a case or proceeding on behalf of another or providing legal representation with respect to a case or proceeding under this title."],[1,"(5) The term \"claim\" means—"],[2,"(A) right to payment, whether or not such right is reduced to judgment, liquidated, unliquidated, fixed, contingent, matured, unmatured, disputed, undisputed, legal, equitable, secured, or unsecured; or"],[2,"(B) right to an equitable remedy for breach of performance if such breach gives rise to a right to payment, whether or not such right to an equitable remedy is reduced to judgment, fixed, contingent, matured, unmatured, disputed, undisputed, secured, or unsecured."],[1,"(6) The term \"commodity broker\" means futures commission merchant, foreign futures commission merchant, clearing organization, leverage transaction merchant, or commodity options dealer, as defined in section 761 of this title, with respect to which there is a customer, as defined in section 761 of this title."],[1,"(7) The term \"community claim\" means claim that arose before the commencement of the case concerning the debtor for which property of the kind specified in section 541(a)(2) of this title is liable, whether or not there is any such property at the time of the commencement of the case."],[1,"(7A) The term \"commercial fishing operation\" means—"],[2,"(A) the catching or harvesting of fish, shrimp, lobsters, urchins, seaweed, shellfish, or other aquatic species or products of such species; or"],[2,"(B) for purposes of section 109 and chapter 12, aquaculture activities consisting of raising for market any species or product described in subparagraph (A)."],[1,"(7B) The term \"commercial fishing vessel\" means a vessel used by a family fisherman to carry out a commercial fishing operation."],[1,"(8) The term \"consumer debt\" means debt incurred by an individual primarily for a personal, family, or household purpose."],[1,"(9) The term \"corporation\"—"],[2,"(A) includes—"],[3,"(i) association having a power or privilege that a private corporation, but not an individual or a partnership, possesses;"],[3,"(ii) partnership association organized under a law that makes only the capital subscribed responsible for the debts of such association;"],[3,"(iii) joint-stock company;"],[3,"(iv) unincorporated company or association; or"],[3,"(v) business trust; but"],[2,"(B) does not include limited partnership."],[1,"(10) The term \"creditor\" means—"],[2,"(A) entity that has a claim against the debtor that arose at the time of or before the order for relief concerning the debtor;"],[2,"(B) entity that has a claim against the estate of a kind specified in section 348(d), 502(f), 502(g), 502(h) or 502(i) of this title; or"],[2,"(C) entity that has a community claim."],[1,"(10A) The term \"current monthly income\"—"],[2,"(A) means the average monthly income from all sources that the debtor receives (or in a joint case the debtor and the debtor's spouse receive) without regard to whether such income is taxable income, derived during the 6-month period ending on—"],[3,"(i) the last day of the calendar month immediately preceding the date of the commencement of the case if the debtor files the schedule of current income required by section 521(a)(1)(B)(ii); or"],[3,"(ii) the date on which current income is determined by the court for purposes of this title if the debtor does not file the schedule of current income required by section 521(a)(1)(B)(ii); and"],[2,"(B)(i) includes any amount paid by any entity other than the debtor (or in a joint case the debtor and the debtor's spouse), on a regular basis for the household expenses of the debtor or the debtor's dependents (and in a joint case the debtor's spouse if not otherwise a dependent); and"],[2,"(ii) excludes—"],[3,"(I) benefits received under the Social Security Act (42 U.S.C. 301 et seq.);"],[3,"(II) payments to victims of war crimes or crimes against humanity on account of their status as victims of such crimes;"],[3,"(III) payments to victims of international terrorism or domestic terrorism, as those terms are defined in section 2331 of title 18, on account of their status as victims of such terrorism; and"],[3,"(IV) any monthly compensation, pension, pay, annuity, or allowance paid under title 10, 37, or 38 in connection with a disability, combat-related injury or disability, or death of a member of the uniformed services, except that any retired pay excluded under this subclause shall include retired pay paid under chapter 61 of title 10 only to the extent that such retired pay exceeds the amount of retired pay to which the debtor would otherwise be entitled if retired under any provision of title 10 other than chapter 61 of that title."],[1,"(11) The term \"custodian\" means—"],[2,"(A) receiver or trustee of any of the property of the debtor, appointed in a case or proceeding not under this title;"],[2,"(B) assignee under a general assignment for the benefit of the debtor's creditors; or"],[2,"(C) trustee, receiver, or agent under applicable law, or under a contract, that is appointed or authorized to take charge of property of the debtor for the purpose of enforcing a lien against such property, or for the purpose of general administration of such property for the benefit of the debtor's creditors."],[1,"(12) The term \"debt\" means liability on a claim."],[1,"(12A) The term \"debt relief agency\" means any person who provides any bankruptcy assistance to an assisted person in return for the payment of money or other valuable consideration, or who is a bankruptcy petition preparer under section 110, but does not include—"],[2,"(A) any person who is an officer, director, employee, or agent of a person who provides such assistance or of the bankruptcy petition preparer;"],[2,"(B) a nonprofit organization that is exempt from taxation under section 501(c)(3) of the Internal Revenue Code of 1986;"],[2,"(C) a creditor of such assisted person, to the extent that the creditor is assisting such assisted person to restructure any debt owed by such assisted person to the creditor;"],[2,"(D) a depository institution (as defined in section 3 of the Federal Deposit Insurance Act) or any Federal credit union or State credit union (as those terms are defined in section 101 of the Federal Credit Union Act), or any affiliate or subsidiary of such depository institution or credit union; or"],[2,"(E) an author, publisher, distributor, or seller of works subject to copyright protection under title 17, when acting in such capacity."],[1,"(13) The term \"debtor\" means person or municipality concerning which a case under this title has been commenced."],[1,"(13A) The term \"debtor's principal residence\"—"],[2,"(A) means a residential structure if used as the principal residence by the debtor, including incidental property, without regard to whether that structure is attached to real property; and"],[2,"(B) includes an individual condominium or cooperative unit, a mobile or manufactured home, or trailer if used as the principal residence by the debtor."],[1,"(14) The term \"disinterested person\" means a person that—"],[2,"(A) is not a creditor, an equity security holder, or an insider;"],[2,"(B) is not and was not, within 2 years before the date of the filing of the petition, a director, officer, or employee of the debtor; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/101?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§101. Definitions","tname":"Bankruptcy","by":{"1":"33, 33, 33"}},{"t":"usc","label":"11 U.S.C. § 362","url":"https://www.law.cornell.edu/uscode/text/11/362","subs":["(a)","(a)(4)","(a)(5)","(b)","(b)(4)"],"stext":{"head":"§362. Automatic stay","paras":[[0,"(a) Except as provided in subsection (b) of this section, a petition filed under section 301, 302, or 303 of this title, or an application filed under section 5(a)(3) of the Securities Investor Protection Act of 1970, operates as a stay, applicable to all entities, of—"],[1,"(1) the commencement or continuation, including the issuance or employment of process, of a judicial, administrative, or other action or proceeding against the debtor that was or could have been commenced before the commencement of the case under this title, or to recover a claim against the debtor that arose before the commencement of the case under this title;"],[1,"(2) the enforcement, against the debtor or against property of the estate, of a judgment obtained before the commencement of the case under this title;"],[1,"(3) any act to obtain possession of property of the estate or of property from the estate or to exercise control over property of the estate;"],[1,"(4) any act to create, perfect, or enforce any lien against property of the estate;"],[1,"(5) any act to create, perfect, or enforce against property of the debtor any lien to the extent that such lien secures a claim that arose before the commencement of the case under this title;"],[1,"(6) any act to collect, assess, or recover a claim against the debtor that arose before the commencement of the case under this title;"],[1,"(7) the setoff of any debt owing to the debtor that arose before the commencement of the case under this title against any claim against the debtor; and"],[1,"(8) the commencement or continuation of a proceeding before the United States Tax Court concerning a tax liability of a debtor that is a corporation for a taxable period the bankruptcy court may determine or concerning the tax liability of a debtor who is an individual for a taxable period ending before the date of the order for relief under this title."],[0,"(b) The filing of a petition under section 301, 302, or 303 of this title, or of an application under section 5(a)(3) of the Securities Investor Protection Act of 1970, does not operate as a stay—"],[1,"(1) under subsection (a) of this section, of the commencement or continuation of a criminal action or proceeding against the debtor;"],[1,"(2) under subsection (a)—"],[2,"(A) of the commencement or continuation of a civil action or proceeding—"],[3,"(i) for the establishment of paternity;"],[3,"(ii) for the establishment or modification of an order for domestic support obligations;"],[3,"(iii) concerning child custody or visitation;"],[3,"(iv) for the dissolution of a marriage, except to the extent that such proceeding seeks to determine the division of property that is property of the estate; or"],[3,"(v) regarding domestic violence;"],[2,"(B) of the collection of a domestic support obligation from property that is not property of the estate;"],[2,"(C) with respect to the withholding of income that is property of the estate or property of the debtor for payment of a domestic support obligation under a judicial or administrative order or a statute;"],[2,"(D) of the withholding, suspension, or restriction of a driver's license, a professional or occupational license, or a recreational license, under State law, as specified in section 466(a)(16) of the Social Security Act;"],[2,"(E) of the reporting of overdue support owed by a parent to any consumer reporting agency as specified in section 466(a)(7) of the Social Security Act;"],[2,"(F) of the interception of a tax refund, as specified in sections 464 and 466(a)(3) of the Social Security Act or under an analogous State law; or"],[2,"(G) of the enforcement of a medical obligation, as specified under title IV of the Social Security Act;"],[1,"(3) under subsection (a) of this section, of any act to perfect, or to maintain or continue the perfection of, an interest in property to the extent that the trustee's rights and powers are subject to such perfection under section 546(b) of this title or to the extent that such act is accomplished within the period provided under section 547(e)(2)(A) of this title;"],[1,"(4) under paragraph (1), (2), (3), or (6) of subsection (a) of this section, of the commencement or continuation of an action or proceeding by a governmental unit or any organization exercising authority under the Convention on the Prohibition of the Development, Production, Stockpiling and Use of Chemical Weapons and on Their Destruction, opened for signature on January 13, 1993, to enforce such governmental unit's or organization's police and regulatory power, including the enforcement of a judgment other than a money judgment, obtained in an action or proceeding by the governmental unit to enforce such governmental unit's or organization's police or regulatory power;"],[1,"[(5) Repealed. Pub. L. 105–277, div. I, title VI, §603(1), Oct. 21, 1998, 112 Stat. 2681–866;]"],[1,"(6) under subsection (a) of this section, of the exercise by a commodity broker, forward contract merchant, stockbroker, financial institution, financial participant, or securities clearing agency of any contractual right (as defined in section 555 or 556) under any security agreement or arrangement or other credit enhancement forming a part of or related to any commodity contract, forward contract or securities contract, or of any contractual right (as defined in section 555 or 556) to offset or net out any termination value, payment amount, or other transfer obligation arising under or in connection with 1 or more such contracts, including any master agreement for such contracts;"],[1,"(7) under subsection (a) of this section, of the exercise by a repo participant or financial participant of any contractual right (as defined in section 559) under any security agreement or arrangement or other credit enhancement forming a part of or related to any repurchase agreement, or of any contractual right (as defined in section 559) to offset or net out any termination value, payment amount, or other transfer obligation arising under or in connection with 1 or more such agreements, including any master agreement for such agreements;"],[1,"(8) under subsection (a) of this section, of the commencement of any action by the Secretary of Housing and Urban Development to foreclose a mortgage or deed of trust in any case in which the mortgage or deed of trust held by the Secretary is insured or was formerly insured under the National Housing Act and covers property, or combinations of property, consisting of five or more living units;"],[1,"(9) under subsection (a), of—"],[2,"(A) an audit by a governmental unit to determine tax liability;"],[2,"(B) the issuance to the debtor by a governmental unit of a notice of tax deficiency;"],[2,"(C) a demand for tax returns; or"],[2,"(D) the making of an assessment for any tax and issuance of a notice and demand for payment of such an assessment (but any tax lien that would otherwise attach to property of the estate by reason of such an assessment shall not take effect unless such tax is a debt of the debtor that will not be discharged in the case and such property or its proceeds are transferred out of the estate to, or otherwise revested in, the debtor)."],[1,"(10) under subsection (a) of this section, of any act by a lessor to the debtor under a lease of nonresidential real property that has terminated by the expiration of the stated term of the lease before the commencement of or during a case under this title to obtain possession of such property;"],[1,"(11) under subsection (a) of this section, of the presentment of a negotiable instrument and the giving of notice of and protesting dishonor of such an instrument;"],[1,"(12) under subsection (a) of this section, after the date which is 90 days after the filing of such petition, of the commencement or continuation, and conclusion to the entry of final judgment, of an action which involves a debtor subject to reorganization pursuant to chapter 11 of this title and which was brought by the Secretary of Transportation under section 31325 of title 46 (including distribution of any proceeds of sale) to foreclose a preferred ship or fleet mortgage, or a security interest in or relating to a vessel or vessel under construction, held by the Secretary of Transportation under chapter 537 of title 46 or section 109(h) of title 49, or under applicable State law;"],[1,"(13) under subsection (a) of this section, after the date which is 90 days after the filing of such petition, of the commencement or continuation, and conclusion to the entry of final judgment, of an action which involves a debtor subject to reorganization pursuant to chapter 11 of this title and which was brought by the Secretary of Commerce under section 31325 of title 46 (including distribution of any proceeds of sale) to foreclose a preferred ship or fleet mortgage in a vessel or a mortgage, deed of trust, or other security interest in a fishing facility held by the Secretary of Commerce under chapter 537 of title 46;"],[1,"(14) under subsection (a) of this section, of any action by an accrediting agency regarding the accreditation status of the debtor as an educational institution;"],[1,"(15) under subsection (a) of this section, of any action by a State licensing body regarding the licensure of the debtor as an educational institution;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/362?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§362. Automatic stay","tname":"Bankruptcy","by":{"1":"43, 44, 11, 46, 46, 46, 11, 12, 18, 43, 44, 45, 46"}},{"t":"usc","label":"11 U.S.C. § 363","url":"https://www.law.cornell.edu/uscode/text/11/363","subs":["(c)"],"by":{"1":"26"}},{"t":"usc","label":"11 U.S.C. § 365","url":"https://www.law.cornell.edu/uscode/text/11/365","subs":["(b)","(b)(1)(C)"],"by":{"1":"34, 33, 33"}},{"t":"usc","label":"11 U.S.C. § 525","url":"https://www.law.cornell.edu/uscode/text/11/525","subs":["(a)"],"stext":{"head":"§525. Protection against discriminatory treatment","paras":[[0,"(a) Except as provided in the Perishable Agricultural Commodities Act, 1930, the Packers and Stockyards Act, 1921, and section 1 of the Act entitled \"An Act making appropriations for the Department of Agriculture for the fiscal year ending June 30, 1944, and for other purposes,\" approved July 12, 1943, a governmental unit may not deny, revoke, suspend, or refuse to renew a license, permit, charter, franchise, or other similar grant to, condition such a grant to, discriminate with respect to such a grant against, deny employment to, terminate the employment of, or discriminate with respect to employment against, a person that is or has been a debtor under this title or a bankrupt or a debtor under the Bankruptcy Act, or another person with whom such bankrupt or debtor has been associated, solely because such bankrupt or debtor is or has been a debtor under this title or a bankrupt or debtor under the Bankruptcy Act, has been insolvent before the commencement of the case under this title, or during the case but before the debtor is granted or denied a discharge, or has not paid a debt that is dischargeable in the case under this title or that was discharged under the Bankruptcy Act."],[0,"(b) No private employer may terminate the employment of, or discriminate with respect to employment against, an individual who is or has been a debtor under this title, a debtor or bankrupt under the Bankruptcy Act, or an individual associated with such debtor or bankrupt, solely because such debtor or bankrupt—"],[1,"(1) is or has been a debtor under this title or a debtor or bankrupt under the Bankruptcy Act;"],[1,"(2) has been insolvent before the commencement of a case under this title or during the case but before the grant or denial of a discharge; or"],[1,"(3) has not paid a debt that is dischargeable in a case under this title or that was discharged under the Bankruptcy Act."],[0,"(c)(1) A governmental unit that operates a student grant or loan program and a person engaged in a business that includes the making of loans guaranteed or insured under a student loan program may not deny a student grant, loan, loan guarantee, or loan insurance to a person that is or has been a debtor under this title or a bankrupt or debtor under the Bankruptcy Act, or another person with whom the debtor or bankrupt has been associated, because the debtor or bankrupt is or has been a debtor under this title or a bankrupt or debtor under the Bankruptcy Act, has been insolvent before the commencement of a case under this title or during the pendency of the case but before the debtor is granted or denied a discharge, or has not paid a debt that is dischargeable in the case under this title or that was discharged under the Bankruptcy Act."],[0,"(2) In this section, \"student loan program\" means any program operated under title IV of the Higher Education Act of 1965 or a similar program operated under State or local law."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/525?type=usc&year=mostrecent&link-type=html"},"op":16,"head":"§525. Protection against discriminatory treatment","tname":"Bankruptcy","by":{"1":"passim, passim"}},{"t":"usc","label":"11 U.S.C. § 544","url":"https://www.law.cornell.edu/uscode/text/11/544","stext":{"head":"§544. Trustee as lien creditor and as successor to certain creditors and purchasers","paras":[[0,"(a) The trustee shall have, as of the commencement of the case, and without regard to any knowledge of the trustee or of any creditor, the rights and powers of, or may avoid any transfer of property of the debtor or any obligation incurred by the debtor that is voidable by—"],[1,"(1) a creditor that extends credit to the debtor at the time of the commencement of the case, and that obtains, at such time and with respect to such credit, a judicial lien on all property on which a creditor on a simple contract could have obtained such a judicial lien, whether or not such a creditor exists;"],[1,"(2) a creditor that extends credit to the debtor at the time of the commencement of the case, and obtains, at such time and with respect to such credit, an execution against the debtor that is returned unsatisfied at such time, whether or not such a creditor exists; or"],[1,"(3) a bona fide purchaser of real property, other than fixtures, from the debtor, against whom applicable law permits such transfer to be perfected, that obtains the status of a bona fide purchaser and has perfected such transfer at the time of the commencement of the case, whether or not such a purchaser exists."],[0,"(b)(1) Except as provided in paragraph (2), the trustee may avoid any transfer of an interest of the debtor in property or any obligation incurred by the debtor that is voidable under applicable law by a creditor holding an unsecured claim that is allowable under section 502 of this title or that is not allowable only under section 502(e) of this title."],[0,"(2) Paragraph (1) shall not apply to a transfer of a charitable contribution (as that term is defined in section 548(d)(3)) that is not covered under section 548(a)(1)(B), by reason of section 548(a)(2). Any claim by any person to recover a transferred contribution described in the preceding sentence under Federal or State law in a Federal or State court shall be preempted by the commencement of the case."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/544?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§544. Trustee as lien creditor and as successor to certain creditors and purchasers","tname":"Bankruptcy","by":{"1":"11"}},{"t":"usc","label":"11 U.S.C. § 1141","url":"https://www.law.cornell.edu/uscode/text/11/1141","subs":["(d)(1)","(d)(1)(A)"],"stext":{"head":"§1141. Effect of confirmation","paras":[[0,"(a) Except as provided in subsections (d)(2) and (d)(3) of this section, the provisions of a confirmed plan bind the debtor, any entity issuing securities under the plan, any entity acquiring property under the plan, and any creditor, equity security holder, or general partner in the debtor, whether or not the claim or interest of such creditor, equity security holder, or general partner is impaired under the plan and whether or not such creditor, equity security holder, or general partner has accepted the plan."],[0,"(b) Except as otherwise provided in the plan or the order confirming the plan, the confirmation of a plan vests all of the property of the estate in the debtor."],[0,"(c) Except as provided in subsections (d)(2) and (d)(3) of this section and except as otherwise provided in the plan or in the order confirming the plan, after confirmation of a plan, the property dealt with by the plan is free and clear of all claims and interests of creditors, equity security holders, and of general partners in the debtor."],[0,"(d)(1) Except as otherwise provided in this subsection, in the plan, or in the order confirming the plan, the confirmation of a plan—"],[1,"(A) discharges the debtor from any debt that arose before the date of such confirmation, and any debt of a kind specified in section 502(g), 502(h), or 502(i) of this title, whether or not—"],[2,"(i) a proof of the claim based on such debt is filed or deemed filed under section 501 of this title;"],[2,"(ii) such claim is allowed under section 502 of this title; or"],[2,"(iii) the holder of such claim has accepted the plan; and"],[1,"(B) terminates all rights and interests of equity security holders and general partners provided for by the plan."],[0,"(2) A discharge under this chapter does not discharge a debtor who is an individual from any debt excepted from discharge under section 523 of this title."],[0,"(3) The confirmation of a plan does not discharge a debtor if—"],[1,"(A) the plan provides for the liquidation of all or substantially all of the property of the estate;"],[1,"(B) the debtor does not engage in business after consummation of the plan; and"],[1,"(C) the debtor would be denied a discharge under section 727(a) of this title if the case were a case under chapter 7 of this title."],[0,"(4) The court may approve a written waiver of discharge executed by the debtor after the order for relief under this chapter."],[0,"(5) In a case in which the debtor is an individual—"],[1,"(A) unless after notice and a hearing the court orders otherwise for cause, confirmation of the plan does not discharge any debt provided for in the plan until the court grants a discharge on completion of all payments under the plan;"],[1,"(B) at any time after the confirmation of the plan, and after notice and a hearing, the court may grant a discharge to the debtor who has not completed payments under the plan if—"],[2,"(i) the value, as of the effective date of the plan, of property actually distributed under the plan on account of each allowed unsecured claim is not less than the amount that would have been paid on such claim if the estate of the debtor had been liquidated under chapter 7 on such date;"],[2,"(ii) modification of the plan under section 1127 is not practicable; and"],[2,"(iii) subparagraph (C) permits the court to grant a discharge; and"],[1,"(C) the court may grant a discharge if, after notice and a hearing held not more than 10 days before the date of the entry of the order granting the discharge, the court finds that there is no reasonable cause to believe that—"],[2,"(i) section 522(q)(1) may be applicable to the debtor; and"],[2,"(ii) there is pending any proceeding in which the debtor may be found guilty of a felony of the kind described in section 522(q)(1)(A) or liable for a debt of the kind described in section 522(q)(1)(B);"],[1,"and if the requirements of subparagraph (A) or (B) are met."],[1,"(6) Notwithstanding paragraph (1), the confirmation of a plan does not discharge a debtor that is a corporation from any debt—"],[2,"(A) of a kind specified in paragraph (2)(A) or (2)(B) of section 523(a) that is owed to a domestic governmental unit, or owed to a person as the result of an action filed under subchapter III of chapter 37 of title 31 or any similar State statute; or"],[2,"(B) for a tax or customs duty with respect to which the debtor—"],[3,"(i) made a fraudulent return; or"],[3,"(ii) willfully attempted in any manner to evade or to defeat such tax or such customs duty."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/1141?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1141. Effect of confirmation","tname":"Bankruptcy","by":{"1":"31, 32"}},{"t":"usc","label":"47 U.S.C. § 151","url":"https://www.law.cornell.edu/uscode/text/47/151","by":{"1":"2, 22, 27"}},{"t":"usc","label":"47 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/47/301","by":{"1":"2, 22, 27"}},{"t":"usc","label":"47 U.S.C. § 309","url":"https://www.law.cornell.edu/uscode/text/47/309","subs":["(a)","(i)","(j)(1)","(j)(3)(B)","(j)(3)(D)","(j)(4)(A)","(j)(6)(C)","(j)(6)(D)","(j)(7)(B)"],"stext":{"head":"§309. Application for license","paras":[[0,"(a) Considerations in granting application"],[0,"Subject to the provisions of this section, the Commission shall determine, in the case of each application filed with it to which section 308 of this title applies, whether the public interest, convenience, and necessity will be served by the granting of such application, and, if the Commission, upon examination of such application and upon consideration of such other matters as the Commission may officially notice, shall find that public interest, convenience, and necessity would be served by the granting thereof, it shall grant such application."],[0,"(b) Time of granting application"],[0,"Except as provided in subsection (c) of this section, no such application—"],[1,"(1) for an instrument of authorization in the case of a station in the broadcasting or common carrier services, or"],[1,"(2) for an instrument of authorization in the case of a station in any of the following categories:"],[2,"(A) industrial radio positioning stations for which frequencies are assigned on an exclusive basis,"],[2,"(B) aeronautical en route stations,"],[2,"(C) aeronautical advisory stations,"],[2,"(D) airdrome control stations,"],[2,"(E) aeronautical fixed stations, and"],[2,"(F) such other stations or classes of stations, not in the broadcasting or common carrier services, as the Commission shall by rule prescribe,"],[0,"shall be granted by the Commission earlier than thirty days following issuance of public notice by the Commission of the acceptance for filing of such application or of any substantial amendment thereof."],[0,"(c) Applications not affected by subsection (b)"],[0,"Subsection (b) of this section shall not apply—"],[1,"(1) to any minor amendment of an application to which such subsection is applicable, or"],[1,"(2) to any application for—"],[2,"(A) a minor change in the facilities of an authorized station,"],[2,"(B) consent to an involuntary assignment or transfer under section 310(b) of this title or to an assignment or transfer thereunder which does not involve a substantial change in ownership or control,"],[2,"(C) a license under section 319(c) of this title or, pending application for or grant of such license, any special or temporary authorization to permit interim operation to facilitate completion of authorized construction or to provide substantially the same service as would be authorized by such license,"],[2,"(D) extension of time to complete construction of authorized facilities,"],[2,"(E) an authorization of facilities for remote pickups, studio links and similar facilities for use in the operation of a broadcast station,"],[2,"(F) authorizations pursuant to section 325(c) of this title where the programs to be transmitted are special events not of a continuing nature,"],[2,"(G) a special temporary authorization for nonbroadcast operation not to exceed thirty days where no application for regular operation is contemplated to be filed or not to exceed sixty days pending the filing of an application for such regular operation, or"],[2,"(H) an authorization under any of the proviso clauses of section 308(a) of this title."],[0,"(d) Petition to deny application; time; contents; reply; findings"],[0,"(1) Any party in interest may file with the Commission a petition to deny any application (whether as originally filed or as amended) to which subsection (b) of this section applies at any time prior to the day of Commission grant thereof without hearing or the day of formal designation thereof for hearing; except that with respect to any classification of applications, the Commission from time to time by rule may specify a shorter period (no less than thirty days following the issuance of public notice by the Commission of the acceptance for filing of such application or of any substantial amendment thereof), which shorter period shall be reasonably related to the time when the applications would normally be reached for processing. The petitioner shall serve a copy of such petition on the applicant. The petition shall contain specific allegations of fact sufficient to show that the petitioner is a party in interest and that a grant of the application would be prima facie inconsistent with subsection (a) (or subsection (k) in the case of renewal of any broadcast station license). Such allegations of fact shall, except for those of which official notice may be taken, be supported by affidavit of a person or persons with personal knowledge thereof. The applicant shall be given the opportunity to file a reply in which allegations of fact or denials thereof shall similarly be supported by affidavit."],[0,"(2) If the Commission finds on the basis of the application, the pleadings filed, or other matters which it may officially notice that there are no substantial and material questions of fact and that a grant of the application would be consistent with subsection (a) (or subsection (k) in the case of renewal of any broadcast station license), it shall make the grant, deny the petition, and issue a concise statement of the reasons for denying the petition, which statement shall dispose of all substantial issues raised by the petition. If a substantial and material question of fact is presented or if the Commission for any reason is unable to find that grant of the application would be consistent with subsection (a) (or subsection (k) in the case of renewal of any broadcast station license), it shall proceed as provided in subsection (e)."],[0,"(e) Hearings; intervention; evidence; burden of proof"],[0,"If, in the case of any application to which subsection (a) of this section applies, a substantial and material question of fact is presented or the Commission for any reason is unable to make the finding specified in such subsection, it shall formally designate the application for hearing on the ground or reasons then obtaining and shall forthwith notify the applicant and all other known parties in interest of such action and the grounds and reasons therefor, specifying with particularity the matters and things in issue but not including issues or requirements phrased generally. When the Commission has so designated an application for hearing the parties in interest, if any, who are not notified by the Commission of such action may acquire the status of a party to the proceeding thereon by filing a petition for intervention showing the basis for their interest not more than thirty days after publication of the hearing issues or any substantial amendment thereto in the Federal Register. Any hearing subsequently held upon such application shall be a full hearing in which the applicant and all other parties in interest shall be permitted to participate. The burden of proceeding with the introduction of evidence and the burden of proof shall be upon the applicant, except that with respect to any issue presented by a petition to deny or a petition to enlarge the issues, such burdens shall be as determined by the Commission."],[0,"(f) Temporary authorization of temporary operations under subsection (b)"],[0,"When an application subject to subsection (b) has been filed, the Commission, notwithstanding the requirements of such subsection, may, if the grant of such application is otherwise authorized by law and if it finds that there are extraordinary circumstances requiring temporary operations in the public interest and that delay in the institution of such temporary operations would seriously prejudice the public interest, grant a temporary authorization, accompanied by a statement of its reasons therefor, to permit such temporary operations for a period not exceeding 180 days, and upon making like findings may extend such temporary authorization for additional periods not to exceed 180 days. When any such grant of a temporary authorization is made, the Commission shall give expeditious treatment to any timely filed petition to deny such application and to any petition for rehearing of such grant filed under section 405 of this title."],[0,"(g) Classification of applications"],[0,"The Commission is authorized to adopt reasonable classifications of applications and amendments in order to effectuate the purposes of this section."],[0,"(h) Form and conditions of station licenses"],[0,"Such station licenses as the Commission may grant shall be in such general form as it may prescribe, but each license shall contain, in addition to other provisions, a statement of the following conditions to which such license shall be subject: (1) The station license shall not vest in the licensee any right to operate the station nor any right in the use of the frequencies designated in the license beyond the term thereof nor in any other manner than authorized therein; (2) neither the license nor the right granted thereunder shall be assigned or otherwise transferred in violation of this chapter; (3) every license issued under this chapter shall be subject in terms to the right of use or control conferred by section 606 of this title."],[0,"(i) Random selection"],[0,"(1) General authority.—Except as provided in paragraph (5), if there is more than one application for any initial license or construction permit, then the Commission shall have the authority to grant such license or permit to a qualified applicant through the use of a system of random selection."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/47/309?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§309. Application for license","tname":"Telecommunications","by":{"1":"2, 22, 27, 2, 22, 27, 47, 47, 47, 3, 22, 4, 5, 48, 4, 47, 48, 4, 46, 48, 23"}},{"t":"usc","label":"47 U.S.C. § 310","url":"https://www.law.cornell.edu/uscode/text/47/310","by":{"1":"31"}},{"t":"usc","label":"47 U.S.C. § 402","url":"https://www.law.cornell.edu/uscode/text/47/402","stext":{"head":"§402. Judicial review of Commission's orders and decisions","paras":[[0,"(a) Procedure"],[0,"Any proceeding to enjoin, set aside, annul, or suspend any order of the Commission under this chapter (except those appealable under subsection (b) of this section) shall be brought as provided by and in the manner prescribed in chapter 158 of title 28."],[0,"(b) Right to appeal"],[0,"Appeals may be taken from decisions and orders of the Commission to the United States Court of Appeals for the District of Columbia in any of the following cases:"],[1,"(1) By any applicant for a construction permit or station license, whose application is denied by the Commission."],[1,"(2) By any applicant for the renewal or modification of any such instrument of authorization whose application is denied by the Commission."],[1,"(3) By any party to an application for authority to transfer, assign, or dispose of any such instrument of authorization, or any rights thereunder, whose application is denied by the Commission."],[1,"(4) By any applicant for the permit required by section 325 of this title whose application has been denied by the Commission, or by any permittee under said section whose permit has been revoked by the Commission."],[1,"(5) By the holder of any construction permit or station license which has been modified or revoked by the Commission."],[1,"(6) By any other person who is aggrieved or whose interests are adversely affected by any order of the Commission granting or denying any application described in paragraphs (1), (2), (3), (4), and (9) of this subsection."],[1,"(7) By any person upon whom an order to cease and desist has been served under section 312 of this title."],[1,"(8) By any radio operator whose license has been suspended by the Commission."],[1,"(9) By any applicant for authority to provide interLATA services under section 271 of this title whose application is denied by the Commission."],[1,"(10) By any person who is aggrieved or whose interests are adversely affected by a determination made by the Commission under section 618(a)(3) of this title."],[0,"(c) Filing notice of appeal; contents; jurisdiction; temporary orders"],[0,"Such appeal shall be taken by filing a notice of appeal with the court within thirty days from the date upon which public notice is given of the decision or order complained of. Such notice of appeal shall contain a concise statement of the nature of the proceedings as to which the appeal is taken; a concise statement of the reasons on which the appellant intends to rely, separately stated and numbered; and proof of service of a true copy of said notice and statement upon the Commission. Upon filing of such notice, the court shall have jurisdiction of the proceedings and of the questions determined therein and shall have power, by order, directed to the Commission or any other party to the appeal, to grant such temporary relief as it may deem just and proper. Orders granting temporary relief may be either affirmative or negative in their scope and application so as to permit either the maintenance of the status quo in the matter in which the appeal is taken or the restoration of a position or status terminated or adversely affected by the order appealed from and shall, unless otherwise ordered by the court, be effective pending hearing and determination of said appeal and compliance by the Commission with the final judgment of the court rendered in said appeal."],[0,"(d) Notice to interested parties; filing of record"],[0,"Upon the filing of any such notice of appeal the appellant shall, not later than five days after the filing of such notice, notify each person shown by the records of the Commission to be interested in said appeal of the filing and pendency of the same. The Commission shall file with the court the record upon which the order complained of was entered, as provided in section 2112 of title 28."],[0,"(e) Intervention"],[0,"Within thirty days after the filing of any such appeal any interested person may intervene and participate in the proceedings had upon said appeal by filing with the court a notice of intention to intervene and a verified statement showing the nature of the interest of such party, together with proof of service of true copies of said notice and statement, both upon appellant and upon the Commission. Any person who would be aggrieved or whose interest would be adversely affected by a reversal or modification of the order of the Commission complained of shall be considered an interested party."],[0,"(f) Records and briefs"],[0,"The record and briefs upon which any such appeal shall be heard and determined by the court shall contain such information and material, and shall be prepared within such time and in such manner as the court may by rule prescribe."],[0,"(g) Time of hearing; procedure"],[0,"The court shall hear and determine the appeal upon the record before it in the manner prescribed by section 706 of title 5."],[0,"(h) Remand"],[0,"In the event that the court shall render a decision and enter an order reversing the order of the Commission, it shall remand the case to the Commission to carry out the judgment of the court and it shall be the duty of the Commission, in the absence of the proceedings to review such judgment, to forthwith give effect thereto, and unless otherwise ordered by the court, to do so upon the basis of the proceedings already had and the record upon which said appeal was heard and determined."],[0,"(i) Judgment for costs"],[0,"The court may, in its discretion, enter judgment for costs in favor of or against an appellant, or other interested parties intervening in said appeal, but not against the Commission, depending upon the nature of the issues involved upon said appeal and the outcome thereof."],[0,"(j) Finality of decision; review by Supreme Court"],[0,"The court's judgment shall be final, subject, however, to review by the Supreme Court of the United States upon writ of certiorari on petition therefor under section 1254 of title 28, by the appellant, by the Commission, or by any interested party intervening in the appeal, or by certification by the court pursuant to the provisions of that section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/47/402?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§402. Judicial review of Commission's orders and decisions","tname":"Telecommunications","by":{"1":"31"}},{"t":"usc","label":"28 U.S.C. § 2342","url":"https://www.law.cornell.edu/uscode/text/28/2342","by":{"1":"31"}},{"t":"law","label":"Pub. L. No. 103-66","url":"https://www.govinfo.gov/link/statute/107/388","by":{"1":"28"}},{"t":"usc","label":"28 U.S.C. § 157","url":"https://www.law.cornell.edu/uscode/text/28/157","subs":["(b)(1)","(b)(2)(L)"],"by":{"1":"32, 32"}},{"t":"usc","label":"28 U.S.C. § 1334","url":"https://www.law.cornell.edu/uscode/text/28/1334","subs":["(a)"],"by":{"1":"32"}}]};